namespace {constexpr double PI_D=3.141592653589793;constexpr double TAU=2*PI_D;}
double SelectedStructuralFaceKernel::clamp(double x,double a,double b){return std::min(b,std::max(a,std::isfinite(x)?x:0));}
double SelectedStructuralFaceKernel::mix(double a,double b,double t){return a+(b-a)*t;}
double SelectedStructuralFaceKernel::smooth(double t){return t*t*(3-2*t);}
double SelectedStructuralFaceKernel::srgb(double c){return c<.04045?c*.0773993808:std::pow(c*.9478672986+.0521327014,2.4);}
SelectedStructuralFaceKernel::V2 SelectedStructuralFaceKernel::vec2(const Variant &value){const Array a=value;return {double(a[0]),double(a[1])};}
int SelectedStructuralFaceKernel::role_id(const String &s){if(s=="static")return STATIC;if(s=="eye_ring")return EYE_RING;if(s=="sclera")return SCLERA;if(s=="iris")return IRIS;if(s=="upper_lash")return UPPER_LASH;if(s=="wing")return WING;if(s=="lower_lash")return LOWER_LASH;if(s=="crease")return CREASE;if(s=="mouth_ring")return MOUTH_RING;if(s=="mouth_cavity")return MOUTH_CAVITY;if(s=="tongue")return TONGUE;if(s=="lips")return LIPS;if(s=="front_profile")return FRONT_PROFILE;return -1;}
SelectedStructuralFaceKernel::State SelectedStructuralFaceKernel::state_of(const Dictionary &s){State r;const String mood=s.get("mood","neutral");r.blink=clamp(double(s.get("blink",0.)));r.talk=clamp(double(s.get("talk",s.get("talking",0.))));r.happy=clamp(double(s.get("happy",mood=="happy"?1.:0.)));r.sad=clamp(double(s.get("sad",mood=="sad"?1.:0.)));r.gaze_x=clamp(double(s.get("gazeX",0.)),-1,1);r.gaze_y=clamp(double(s.get("gazeY",0.)),-1,1);return r;}
double SelectedStructuralFaceKernel::center_at(double y)const{const double yy=clamp(y,-.382,.64);size_t lo=0,hi=outline.size()-1;while(hi-lo>1){const size_t mid=(lo+hi)/2;if(outline[mid].y>=yy)lo=mid;else hi=mid;}const double ay=outline[lo].y,by=outline[hi].y,k=ay==by?0:(ay-yy)/(ay-by);return mix(.023*smooth(clamp((-ay-.1)/.282)),.023*smooth(clamp((-by-.1)/.282)),k);}
double SelectedStructuralFaceKernel::width_at(double y)const{const double yy=clamp(y,-.382,.64);size_t lo=0,hi=outline.size()-1;while(hi-lo>1){const size_t mid=(lo+hi)/2;if(outline[mid].y>=yy)lo=mid;else hi=mid;}const V2 a=outline[lo],b=outline[hi];return std::max(.0001,mix(a.x,b.x,a.y==b.y?0:(a.y-yy)/(a.y-b.y))-center_at(yy));}
SelectedStructuralFaceKernel::Section SelectedStructuralFaceKernel::section(double y)const{Section s;s.y=clamp(y,min_y,max_y);const double p=(s.y-min_y)/(max_y-min_y)*double(table.size()-1);const size_t i=std::min(table.size()-2,size_t(std::floor(p)));const double k=p-double(i);for(size_t n=0;n<10;++n)s.v[n]=mix(table[i][n],table[i+1][n],k);if(s.v[6]<.05){s.v[6]=width_at(s.y);s.v[7]=center_at(s.y);}return s;}
double SelectedStructuralFaceKernel::lateral(const Section&s,double x)const{if(s.v[6]<1e-8)return 0;double u=(x-s.v[7])/s.v[6];if(std::abs(u)>.96){const double w=width_at(s.y);u=w>1e-8?(x-center_at(s.y))/w:0;}u=clamp(u,-1,1);return std::abs(u)>1-1e-6?(u>0?1.:-1.):u;}
