double SelectedStructuralFaceKernel::curve_y(const std::vector<V2>&points,double x){for(size_t i=0;i+1<points.size();++i)if(x<=points[i+1].x){const double t=clamp((x-points[i].x)/(points[i+1].x-points[i].x)),a=points[i==0?0:i-1].y,b=points[i].y,c=points[i+1].y,d=points[std::min(points.size()-1,i+2)].y;return .5*(2*b+(-a+c)*t+(2*a-5*b+4*c-d)*t*t+(-a+3*b-3*c+d)*t*t*t);}return points.back().y;}
double SelectedStructuralFaceKernel::lid_y(const Eye&e,double u,bool top,const State&s){const double x=mix(e.min_x,e.max_x,(u+1)/2),arc=std::pow(std::max(0.,1-u*u),.60),chord=mix(e.upper.front().y,e.upper.back().y,(u+1)/2),closed=chord+(.013+.020*s.happy-.006*s.sad)*arc,open=curve_y(top?e.upper:e.lower,x)+(top?-.022*s.happy-.018*s.sad:.022*s.happy)*arc;return mix(open,closed,s.blink);}
SelectedStructuralFaceKernel::V2 SelectedStructuralFaceKernel::ellipse(const V2&c,double rx,double top,double bottom,double t){const double sine=std::sin(t);return {c.x+rx*std::cos(t),c.y+(sine>=0?top:bottom)*sine};}
SelectedStructuralFaceKernel::V2 SelectedStructuralFaceKernel::aperture(const Eye&e,double t,const State&s){const double u=std::cos(t);return {mix(e.min_x,e.max_x,(u+1)/2),lid_y(e,u,std::sin(t)>=0,s)};}
SelectedStructuralFaceKernel::V2 SelectedStructuralFaceKernel::mouth_point(double t,const State&s)const{const double u=std::cos(t),arc=std::sqrt(std::max(0.,1-u*u)),width=.073+.009*s.happy+.016*s.talk,smile=(.010+.009*s.happy-.017*s.sad)*(u*u-.45),upper=.009*s.talk*arc,lower=-(.053*s.talk+.012*s.happy)*arc;return {mouth_center.x+u*width,mouth_center.y+smile+(std::sin(t)>=0?upper:lower)};}
SelectedStructuralFaceKernel::V2 SelectedStructuralFaceKernel::strip_path(int role,const Eye&e,double u,const State&s)const{if(role==LIPS)return mouth_point(PI_D+PI_D*u,s);if(role==CREASE){const double f=mix(.22,.88,u),x=mix(e.min_x,e.max_x,f);State brow=s;brow.blink=0;return {x,lid_y(e,f*2-1,true,brow)+.060+.002*s.blink+s.sad*.016*(e.index==0?u:1-u)};}return {mix(e.min_x,e.max_x,u),lid_y(e,mix(-1,1,u),role==UPPER_LASH,s)};}
double SelectedStructuralFaceKernel::strip_width(int role,double u,const State&s){if(role==UPPER_LASH)return mix(.006+.028*std::pow(std::sin(PI_D*u),.55),.0025+.0065*std::pow(std::sin(PI_D*u),.65),s.blink);if(role==LOWER_LASH)return .0015+.0016*std::sin(PI_D*u);if(role==CREASE)return .0040*std::pow(std::sin(PI_D*u),.6);const double gap=smooth(clamp((std::abs(u-.5)-.055)/.030)),connected=mix(gap,1,clamp(s.talk*8+s.happy));return (.0027+.0007*std::sin(PI_D*u))*connected;}
std::array<double,3>SelectedStructuralFaceKernel::skin_color(double x,double y){const double blush=std::exp(-std::pow((x+.29)/.17,2)-std::pow((y+.17)/.105,2))+1.08*std::exp(-std::pow((x-.32)/.16,2)-std::pow((y+.17)/.105,2)),shadow=std::max(x,0.)*12;return {srgb(clamp((205-16*x+10*std::min(y,0.)+4*blush-shadow)/255)),srgb(clamp((193-15*x+7*std::min(y,0.)-25*blush-shadow)/255)),srgb(clamp((177-17*x+6*std::min(y,0.)-29*blush-shadow)/255))};}
