  const Array spheres=depth_policy.get("eyes",Array());if(p.eye<0||p.eye>=spheres.size())return v.z;const Dictionary e=spheres[p.eye];const Array center=e.get("center",Array()),radii=e.get("radii",Array());if(center.size()!=3)return v.z;const double cx=center[0],cy=center[1],cz=center[2],r=e.get("radius",0.),rx=radii.size()==3?double(radii[0]):r,ry=radii.size()==3?double(radii[1]):r,rz=radii.size()==3?double(radii[2]):r;const double root=rz*std::sqrt(std::max(0.,1-std::pow((v.x-cx)/rx,2)-std::pow((v.y-cy)/ry,2)));const double layer=v.z-front_z(v.x,v.y),sphere=cz+root;
